import { useState, useEffect } from "react";
import axios from "axios";

function App() {

  const [message, setMessage] = useState("");

  const [chatHistory, setChatHistory] = useState([]);

  const [loading, setLoading] = useState(false);

  /* Load chats from localStorage */

  useEffect(() => {

    const savedChats = localStorage.getItem("chatHistory");

    if (savedChats) {

      setChatHistory(JSON.parse(savedChats));
    }

  }, []);

  /* Save chats to localStorage */

 useEffect(() => {

  if (chatHistory.length > 0) {

    localStorage.setItem(
      "chatHistory",
      JSON.stringify(chatHistory)
    );
  }

}, [chatHistory]);
 const sendMessage = async () => {

  if (!message.trim()) return;

  const userMessage = {
    role: "user",
    text: message
  };

  const updatedHistory = [
    ...chatHistory,
    userMessage
  ];

  setChatHistory(updatedHistory);

  setLoading(true);

  try {

    const res = await axios.post(
      "http://127.0.0.1:8000/api/chat",
      {
        message: message
      }
    );

    const aiMessage = {
      role: "ai",
      text: res.data.response
    };

    const finalHistory = [
      ...updatedHistory,
      aiMessage
    ];

    setChatHistory(finalHistory);

    localStorage.setItem(
      "chatHistory",
      JSON.stringify(finalHistory)
    );

  } catch (error) {

    console.log(error);

    const errorHistory = [
      ...updatedHistory,
      {
        role: "ai",
        text: "Backend connection error"
      }
    ];

    setChatHistory(errorHistory);

    localStorage.setItem(
      "chatHistory",
      JSON.stringify(errorHistory)
    );
  }

  setMessage("");

  setLoading(false);
};

  /* Send message using Enter key */

  const handleKeyPress = (e) => {

    if (e.key === "Enter") {

      sendMessage();
    }
  };

  /* Clear Chat */

  const clearChat = () => {

    setChatHistory([]);

    localStorage.removeItem("chatHistory");
  };

  return (

    <div className="flex h-screen bg-slate-950 text-white">

      {/* Sidebar */}

      <div className="w-72 bg-slate-900 border-r border-slate-800 p-5 flex flex-col">

        <h1 className="text-2xl font-bold text-cyan-400 mb-8">
          AI College Companion
        </h1>

        <button
          className="w-full bg-cyan-500 hover:bg-cyan-600 p-3 rounded-xl font-semibold"
          onClick={clearChat}
        >
          + New Chat
        </button>

        <div className="mt-8 overflow-y-auto">

          <h2 className="text-gray-400 mb-4">
            Chat History
          </h2>

          {
            chatHistory
              .filter(chat => chat.role === "user")
              .map((chat, index) => (

                <div
                  key={index}
                  className="bg-slate-800 p-3 rounded-lg mb-3 text-sm truncate hover:bg-slate-700 cursor-pointer"
                >
                  {chat.text}
                </div>

              ))
          }

        </div>

      </div>

      {/* Main Chat Area */}

      <div className="flex-1 flex flex-col">

        {/* Header */}

        <div className="p-5 border-b border-slate-800 text-2xl font-semibold text-cyan-300">
          AI Assistant
        </div>

        {/* Chat Messages */}

        <div className="flex-1 overflow-y-auto p-6 space-y-5">

          {
            chatHistory.map((chat, index) => (

              <div
                key={index}
                className={`max-w-3xl p-4 rounded-2xl leading-7 whitespace-pre-wrap ${
                  chat.role === "user"
                    ? "bg-cyan-500 ml-auto text-white"
                    : "bg-slate-800 text-gray-200"
                }`}
              >

                {chat.text}

              </div>

            ))
          }

          {
            loading && (

              <div className="bg-slate-800 text-gray-400 p-4 rounded-2xl w-fit animate-pulse">
                AI is thinking...
              </div>

            )
          }

        </div>

        {/* Input Area */}

        <div className="p-5 border-t border-slate-800 flex gap-4">

          <input
            type="text"
            placeholder="Ask anything..."
            value={message}
            onChange={(e) =>
              setMessage(e.target.value)
            }
            onKeyDown={handleKeyPress}
            className="flex-1 p-4 rounded-xl bg-slate-800 border border-slate-700 focus:outline-none"
          />

          <button
            onClick={sendMessage}
            className="bg-cyan-500 hover:bg-cyan-600 px-6 rounded-xl font-semibold"
          >
            Send
          </button>

        </div>

      </div>

    </div>
  );
}

export default App;
